(()=>{'use strict';
const events=document.querySelector('#event-list'),courts=document.querySelector('#court-list');
function arrangeEvents(){events?.querySelectorAll('.event').forEach(card=>{const body=card.querySelector(':scope>div:last-child');if(!body)return;let row=body.querySelector(':scope>.hlpb-card-actions');if(!row){row=document.createElement('div');row.className='hlpb-card-actions';const first=body.querySelector(':scope>.text-link,:scope>.hlpb-calendar-add');if(!first)return;first.before(row);}const links=Array.from(body.querySelectorAll(':scope>.text-link,:scope>.hlpb-calendar-add'));links.forEach(el=>row.append(el));const cal=row.querySelector('.hlpb-calendar-add');if(cal&&row.lastElementChild!==cal)row.append(cal);});}
let queued=false;if(events){arrangeEvents();new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;arrangeEvents();});}).observe(events,{childList:true,subtree:true});}
function courtId(name){let hash=2166136261;for(const ch of name){hash^=ch.codePointAt(0);hash=Math.imul(hash,16777619);}return 'court-'+(hash>>>0).toString(36);}
function arrangeCourts(){courts?.querySelectorAll('.card').forEach(card=>{const body=card.querySelector('.card-body'),name=body?.querySelector('h2')?.textContent.trim();if(!name)return;if(!card.id)card.id=courtId(name);if(body.querySelector('.hlpb-court-share'))return;const row=document.createElement('div');row.className='hlpb-card-actions';const actions=Array.from(body.querySelectorAll(':scope>.text-link'));if(actions.length)actions[0].before(row);else body.append(row);actions.forEach(a=>row.append(a));const button=document.createElement('button');button.type='button';button.className='hlpb-court-share';button.textContent='分享場地 ↗';button.setAttribute('aria-label','分享'+name);const status=document.createElement('span');status.className='hlpb-share-status';status.setAttribute('role','status');button.onclick=async()=>{const url=new URL('/courts.html',location.origin);url.hash=card.id;const text='這個花蓮匹克球場地分享給你：'+name;try{if(navigator.share){await navigator.share({title:name+'｜HLPB 花蓮匹克球資訊站',text,url:url.href});}else{await navigator.clipboard.writeText(text+'\n'+url.href);status.textContent='場地連結已複製';}}catch(e){if(e.name!=='AbortError'){status.textContent='請複製此連結';const a=document.createElement('a');a.href=url.href;a.textContent=url.href;status.append(' ',a);}}};row.append(button,status);});}
if(courts){arrangeCourts();new MutationObserver(arrangeCourts).observe(courts,{childList:true});if(location.hash){const id=decodeURIComponent(location.hash.slice(1));const target=document.getElementById(id);if(target&&courts.contains(target))requestAnimationFrame(()=>target.scrollIntoView({block:'center'}));}}
})();